# ---------------------------------------------------------------- layout helper
# X(label, text, y=None, size=32): an APPEAR of a text block at x=410, w=1140.  Pass y for the first block on a slide;
# later blocks without y are stacked under the previous one (estimated height + gap), so every item gets an explicit y.
_NEXT = [60]


def _h(t, size, w):
    per = max(1, int(w / (size * 0.53)))
    lines = 0
    for part in t.split('\n'):
        lines += max(1, -(-len(part) // per))
    return lines * (size * 1.25 + 5)


def X(label, t, y=None, size=32, x=410, w=1140, gap=24):
    """A text block. A block with line breaks becomes one item per line (expanded by _expand below)."""
    if y is None: y = _NEXT[0]
    parts = t.split('\n')
    items, yy = [], y
    for part in parts:
        items.append(T(part, size=size, x=x, y=int(yy), w=w))
        yy += _h(part, size, w) + 4
    _NEXT[0] = int(yy - 4 + gap)
    if len(items) == 1: return A(label, items[0])
    return ('AA', label, items)


def _expand(mods):
    """Turn each multi-line block into consecutive APPEARs (first keeps the label, the rest are marked 'cont.')."""
    for m in mods:
        for sl in m['slides']:
            out = []
            for x in sl['script']:
                if isinstance(x, tuple) and x[0] == 'AA':
                    for i, it in enumerate(x[2]):
                        out.append(A(x[1] if i == 0 else x[1] + ' (line %d)' % (i + 1), it))
                else:
                    out.append(x)
            sl['script'] = out
    return mods


